/*
 * A396641  Centered hexagonal numbers h such that 7*h is also a centered
 *          hexagonal number.
 * https://oeis.org/A396641
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = CH((Y_n+1)/2) where (X_n,Y_n) satisfy X^2-7Y^2=2. The
 *            pair (X,Y) is generated by the linear recurrence
 *            X_{k+1}=8X_k+21Y_k, Y_{k+1}=3X_k+8Y_k starting from
 *            (X_0,Y_0)=(3,1). For n≥1 this yields the sequence of centered
 *            hexagonal numbers h such that 7h is also centered hexagonal
 * Range:     u8 n <= 2, u16 n <= 3, u32 n <= 5, u64 n <= 9, u128 n <= 17,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n) {
    if (n == 0) return 0;          /* offset is 1; below that is undefined */
    seq_t X = 3;                    /* X_0 */
    seq_t Y = 1;                    /* Y_0 */
    for (idx_t i = 1; i < n; ++i) {
        seq_t Xnew = 8*X + 21*Y;
        seq_t Ynew = 3*X + 8*Y;
        X = Xnew;
        Y = Ynew;
    }
    seq_t m = (Y + 1) / 2;          /* m = (Y_n + 1)/2  */
    seq_t h = 3 * m * (m - 1) + 1;  /* centered hexagonal CH(m) */
    return h;
}
